export const getWindDirection = (degrees: number): string => {
  // Normalize degrees to be within [0, 360)
  // The double modulo handles negative numbers correctly if they occur.
  const normalized = ((degrees % 360) + 360) % 360;

  // Calculate the index of the 8-point compass direction.
  // Each sector is 45 degrees wide.
  // We add 22.5 degrees (half a sector) to center the boundaries.
  // Then divide by 45 and floor to get the index 0-7.
  const index = Math.floor((normalized + 22.5) / 45) % 8;

  const directions = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];

  return directions[index];
};
